        assertEquals(2125, bd.getYear());
        assertEquals(2125, bd.getYearOfEra());
        assertEquals(2125, bd.plus(Period.weeks(1)).getWeekyear());

        bd = new DateTime(544, 1, 1, 0, 0, 0, 0, BUDDHIST_UTC);
